insert into public.packages(id,title,tag,destination,duration,price,summary,highlights,itinerary,inclusions,exclusions,terms,cover_path,image_paths,sort_order,active) values ('delhi-agra-jaipur-4n5d-nov2026','Delhi - Agra - Jaipur','04N/05D Group Tour','Delhi · Agra · Jaipur','4 Nights · 5 Days','Ask for price','November 2026 group tour for 40 + 04 adults (44 total), with breakfast and dinner, 3-star hotel stays and a 45-seater AC coach across Delhi, Agra and Jaipur.','["India Gate", "Red Fort", "Qutub Minar", "Taj Mahal", "Agra Fort", "Fatehpur Sikri", "Amber Fort", "City Palace", "Hawa Mahal", "Jal Mahal"]'::jsonb,'[{"day": 1, "title": "Delhi arrival & sightseeing", "meal": "Dinner", "text": "Early morning arrival at Delhi Airport and pickup. Visit India Gate, President House and Parliament House (outside view), Red Fort, Raj Ghat and Qutub Minar. Proceed to the hotel, check in and stay overnight in Delhi."}, {"day": 2, "title": "Delhi - Agra", "meal": "Breakfast · Dinner", "text": "After breakfast, check out from the hotel and drive to Agra by Yamuna Expressway (approximately 5 hours). On arrival, check in at the hotel and stay overnight in Agra."}, {"day": 3, "title": "Agra - Jaipur", "meal": "Breakfast · Dinner", "text": "After breakfast, check out and visit the Taj Mahal, the ivory-white marble mausoleum commissioned in 1632 by Mughal emperor Shah Jahan for Mumtaz, followed by Agra Fort, the historic Mughal fort and former imperial residence. Continue to Jaipur and visit Fatehpur Sikri on the way. On arrival in Jaipur, check in and stay overnight."}, {"day": 4, "title": "Jaipur sightseeing", "meal": "Breakfast · Dinner", "text": "After breakfast, visit City Palace, Jantar Mantar, Amber Fort, Jaigarh Fort, Nahargarh Fort, Albert Hall Museum, Hawa Mahal and Jal Mahal. Return to the hotel and stay overnight in Jaipur."}, {"day": 5, "title": "Jaipur - Delhi drop", "meal": "Breakfast", "text": "After breakfast, check out from the hotel and proceed to Delhi. On arrival, drop at Delhi Airport or Railway Station as per the travel time."}]'::jsonb,'["02 rooms double sharing (as listed in the supplied inclusions)", "Breakfast and dinner at hotel", "All transport and sightseeing by personal vehicle"]'::jsonb,'["Air fare / train fare", "Entrance or monument fees", "Horse, camel or elephant safari and Amer Fort jeep charges", "Meals other than those specified in package inclusions", "Personal expenses such as tips, telephone calls, laundry, liquor and room-heater charges on hill stations", "Any item not specified in package inclusions", "GST 5% on billing"]'::jsonb,'["Child below 5 years is complimentary; above 5 years is chargeable.", "Hotel names are subject to availability at the time of confirmation.", "40% advance payment is required at the time of booking; balance payment should be cleared before 7 days of arrival.", "Cancellation before 15 days of arrival: no charge. Cancellation 10-14 days before arrival: 25% chargeable. Cancellation 5-10 days before arrival: 50% chargeable. Cancellation within 5 days of arrival or no-show: 100% chargeable.", "Refunds are stated to be processed within 15 working days.", "Guests must carry valid photo ID at check-in. Foreign guests must carry a valid passport and visa. Baggage security checks may be carried out before check-in.", "The quotation itself is not booking confirmation. Services can change at confirmation, and rooms remain subject to availability until written confirmation.", "The operator states it is not responsible for unexpected situations such as strikes, road jams, train delays, political disturbances, landslides, road blockages or other natural calamities; extra stay or related charges may be payable by the client.", "Room information in the supplied quotation is inconsistent: the tour details state 10 quad-sharing rooms, while the inclusion list also states 02 rooms double sharing. Final room allocation should be reconfirmed before booking.", "Hotels used: Delhi: Hotel Apra Deluxe / similar - 01 night", "Hotels used: Agra: Hotel The Taj Vilas / similar - 01 night", "Hotels used: Jaipur: Hotel Lords Plaza / Hotel Vesta Maurya Palace / similar - 02 nights", "Tour setup: No. of pax: 40 + 04 adults", "Tour setup: Room plan in tour details: 10 rooms quad sharing (01 king bed + 01 extra bed/mattress)", "Tour setup: Meal plan: MAPAI - breakfast and dinner", "Tour setup: Transport: 45-seater AC coach"]'::jsonb,'local:/assets/packages/delhi-agra-jaipur-4n5d/cover.jpg','[]'::jsonb,100,true) on conflict(id) do update set title=excluded.title,tag=excluded.tag,destination=excluded.destination,duration=excluded.duration,price='Ask for price',summary=excluded.summary,highlights=excluded.highlights,itinerary=excluded.itinerary,inclusions=excluded.inclusions,exclusions=excluded.exclusions,terms=excluded.terms,cover_path=excluded.cover_path,image_paths=excluded.image_paths,active=true;
insert into public.packages(id,title,tag,destination,duration,price,summary,highlights,itinerary,inclusions,exclusions,terms,cover_path,image_paths,sort_order,active) values ('hyderabad-student-3d','Hyderabad Student Package','Student Tour','Hyderabad · Ramoji Film City','3 Days','Ask for price','A student-focused Hyderabad itinerary covering the city’s major heritage attractions, Ramoji Film City, local sightseeing, meals, transport and tour coordination.','["Birla Mandir", "Mecca Masjid", "Ramoji Film City", "Salar Jung Museum", "Golconda Fort", "Charminar", "Lumbini Park", "Nehru Zoological Park"]'::jsonb,'[{"day": 1, "title": "Arrival & sightseeing", "meal": "Lunch · Dinner", "text": "Morning arrival at Hyderabad, receive and transfer to the hotel. After freshening up, proceed to Salar Jung Museum, Charminar and Mecca Masjid (drive through). In the evening visit Birla Mandir, Lumbini Park, Necklace Road, NTR Gardens, New Secretariat Building and the Dr. B. R. Ambedkar 125 ft statue. Night stay at the hotel."}, {"day": 2, "title": "Ramoji Film City tour", "meal": "Breakfast · Lunch · Dinner", "text": "Visit Ramoji Film City from 9 AM to 8 PM. Return for an overnight stay in Hyderabad."}, {"day": 3, "title": "Sightseeing, shopping & departure", "meal": "Breakfast", "text": "Morning check-out. Proceed to Nehru Zoological Park, Salar Jung Museum and Golconda Fort, followed by shopping and a night drop at the railway station."}]'::jsonb,'["A/C transport", "Toll taxes, parking charges and driver allowance", "Meal plan AP all buffet: 2 breakfasts, 2 lunches and 2 dinners", "Sightseeing as per the itinerary", "Accommodation on sharing basis", "Entry ticket charges as per the itinerary", "Tour coordinator"]'::jsonb,'["Extra costs arising due to natural calamities, landslides, road blockage, political disturbances, etc.", "Personal expenses such as laundry, telephone, tips and gratuity", "Soft / hard drinks", "Anything not mentioned in the inclusions", "Extra kilometres used for personal purposes are chargeable"]'::jsonb,'["Sightseeing and operating schedules may need adjustment based on attraction closure days and local conditions.", "Operational notes: Salar Jung Museum and Chowmahalla Palace are closed on Friday.", "Operational notes: Nehru Zoological Park is closed on Monday.", "Operational notes: Carry ID cards, follow group instructions and keep the surroundings clean.", "Booking & cancellation terms from the supplied package: 50% of total cost on booking; full payment 15 days before departure.", "Booking & cancellation terms from the supplied package: More than 15 days before departure: 50% of tour cost cancellation charge.", "Booking & cancellation terms from the supplied package: Less than 15 days and up to 7 days before departure: 75% of tour cost cancellation charge.", "Booking & cancellation terms from the supplied package: Less than 7 days before departure: 100% of tour cost cancellation charge.", "Booking & cancellation terms from the supplied package: Airfare is stated as non-refundable."]'::jsonb,'local:/assets/packages/hyderabad-student-3d/cover.jpg','["local:/assets/packages/hyderabad-student-3d/day-2.jpg", "local:/assets/packages/hyderabad-student-3d/day-3.jpg"]'::jsonb,101,true) on conflict(id) do update set title=excluded.title,tag=excluded.tag,destination=excluded.destination,duration=excluded.duration,price='Ask for price',summary=excluded.summary,highlights=excluded.highlights,itinerary=excluded.itinerary,inclusions=excluded.inclusions,exclusions=excluded.exclusions,terms=excluded.terms,cover_path=excluded.cover_path,image_paths=excluded.image_paths,active=true;
insert into public.packages(id,title,tag,destination,duration,price,summary,highlights,itinerary,inclusions,exclusions,terms,cover_path,image_paths,sort_order,active) values ('manali-delhi-5d4n','Manali - Delhi to Delhi','5 Days / 4 Nights','Delhi · Manali · Solang · Sissu · Kullu','5 Days · 4 Nights','Ask for price','A Delhi-to-Delhi Manali package with Volvo AC semi-sleeper travel, Manali local sightseeing, Solang Valley, Sissu, Atal Tunnel, Kullu and Naggar, with selected adventure activities available at extra cost.','["Hadimba Temple", "Vashisht Temple", "Van Vihar", "Jogini Waterfall Trek", "Mall Road", "Solang Valley", "Sissu", "Atal Tunnel", "Kullu", "Naggar Castle"]'::jsonb,'[{"day": 1, "title": "Board bus to Manali", "meal": "—", "text": "Board the Volvo AC semi-sleeper bus to Manali from Kashmere Gate, Delhi, in the evening / night."}, {"day": 2, "title": "Manali local sightseeing", "meal": "Dinner", "text": "Reach Manali, check in at the hotel and proceed for Manali sightseeing. Visit Hadimba Temple, Vashisht Temple, Van Vihar, Jogini Waterfall trek, Mall Road and Buddhist Monastery. Dinner and overnight stay."}, {"day": 3, "title": "Manali - Solang, Sissu & Atal Tunnel", "meal": "Breakfast · Dinner", "text": "After breakfast, proceed for sightseeing covering Solang Valley, Sissu and Atal Tunnel. Rohtang Pass may be visited if open and carries additional charges. Return for dinner and overnight stay."}, {"day": 4, "title": "Kullu & return Volvo", "meal": "Breakfast", "text": "After breakfast, check out and proceed to Naggar (Kullu), Kullu and Naggar Castle. Adventure activities are available; rafting and paragliding are at additional cost. Board the Volvo bus to Delhi in the evening / night."}, {"day": 5, "title": "Reach Delhi", "meal": "—", "text": "Reach Delhi in the morning."}]'::jsonb,'["Accommodation - 2 nights", "2 breakfasts", "2 dinners", "Private transportation for Manali sightseeing", "Volvo bus tickets (Delhi - Manali)", "Dedicated support team"]'::jsonb,'["Meals not mentioned", "Adventure activities", "Snow coat (available for rent)", "Personal expenses", "Any other expense not mentioned in the inclusions", "Rohtang Pass charges when applicable", "Rafting and paragliding charges"]'::jsonb,'["Child under 5 years: no extra charge; confirm bus-seat availability separately if an extra seat is required.", "Rohtang Pass access is subject to opening conditions, season and local rules."]'::jsonb,'local:/assets/packages/manali-delhi-5d4n/cover.jpg','["local:/assets/packages/manali-delhi-5d4n/manali.jpg", "local:/assets/packages/manali-delhi-5d4n/kullu.jpg"]'::jsonb,102,true) on conflict(id) do update set title=excluded.title,tag=excluded.tag,destination=excluded.destination,duration=excluded.duration,price='Ask for price',summary=excluded.summary,highlights=excluded.highlights,itinerary=excluded.itinerary,inclusions=excluded.inclusions,exclusions=excluded.exclusions,terms=excluded.terms,cover_path=excluded.cover_path,image_paths=excluded.image_paths,active=true;
insert into public.packages(id,title,tag,destination,duration,price,summary,highlights,itinerary,inclusions,exclusions,terms,cover_path,image_paths,sort_order,active) values ('kashmir-srinagar-5d4n','Kashmir - Srinagar to Srinagar','5 Days / 4 Nights','Srinagar · Sonamarg · Gulmarg · Pahalgam','5 Days · 4 Nights','Ask for price','A Srinagar-to-Srinagar Kashmir tour with four nights of accommodation, private transport, breakfast and dinner, a Shikara ride and day excursions to Sonamarg, Gulmarg and Pahalgam.','["Mughal Gardens", "Shikara Ride", "Sonamarg", "Thajiwas Glacier", "Gulmarg", "Gondola Ride", "Pahalgam", "Aru Valley", "Betaab Valley", "Chandanwari"]'::jsonb,'[{"day": 1, "title": "Srinagar arrival & local sightseeing", "meal": "Dinner", "text": "Airport pickup, hotel check-in and Srinagar sightseeing. Visit the Mughal Gardens - Cheshmashahi, Nishat Garden and Shalimar Garden - along with Dargah Hazratbal, Pari Mahal and a Shikara ride. Sightseeing depends on arrival time; remaining local sightseeing can be completed on the last day."}, {"day": 2, "title": "Sonamarg - Meadow of Gold", "meal": "Breakfast · Dinner", "text": "Full-day excursion to Sonamarg. Thajiwas Glacier can be visited by trek / pony ride. Zojila Pass / Zero Point requires a local Union cab. Return after the excursion for dinner."}, {"day": 3, "title": "Gulmarg - Meadow of Flowers", "meal": "Breakfast · Dinner", "text": "Full-day excursion to Gulmarg. Gondola ride and winter snow activities are available at additional charges. Return after sightseeing for dinner."}, {"day": 4, "title": "Pahalgam - Valley of Shepherds", "meal": "Breakfast · Dinner", "text": "Full-day excursion to Pahalgam. Aru Valley, Betaab Valley and Chandanwari are covered by local Union taxi. Baisaran Valley (Mini Switzerland of India) and Tulian Lake can be explored by pony ride / trek."}, {"day": 5, "title": "Srinagar departure", "meal": "Breakfast", "text": "Breakfast, hotel check-out, remaining Srinagar local sightseeing if any, followed by Airport / Railway drop."}]'::jsonb,'["Accommodation - 4 nights", "Private transportation", "4 breakfasts", "4 dinners", "Shikara ride", "Dedicated support team"]'::jsonb,'["Meals not mentioned", "Adventure activities", "Union cabs and pony rides", "Personal expenses", "Snow coat / boot", "Any other expense not mentioned in the inclusions"]'::jsonb,'["Srinagar local sightseeing that cannot be completed on arrival day can be moved to the last day.", "Sonamarg local travel notes: A separate local Union taxi is required in Sonamarg for Zero Point; outside commercial taxis are not permitted for local sightseeing.", "Sonamarg local travel notes: Thajiwas Glacier is stated to be around 4 km from Sonamarg.", "Gulmarg activity notes: Gondola ride and winter snow activities are additional-charge activities.", "Pahalgam local travel notes: Pahalgam Union Taxi operators are stated as the authorized providers for sightseeing to Aru Valley, Betaab Valley and Chandanwari.", "Staying connected in Kashmir: The supplied guide states that postpaid SIMs or prepaid SIM cards from Jammu & Kashmir are functional in the region, while prepaid SIMs from other states will not work.", "Staying connected in Kashmir: It suggests converting an existing SIM to postpaid or purchasing a prepaid SIM in Jammu & Kashmir; hotel Wi-Fi is also stated as available."]'::jsonb,'local:/assets/packages/kashmir-5d4n/cover.jpg','["local:/assets/packages/kashmir-5d4n/sonamarg.jpg", "local:/assets/packages/kashmir-5d4n/gulmarg.jpg"]'::jsonb,103,true) on conflict(id) do update set title=excluded.title,tag=excluded.tag,destination=excluded.destination,duration=excluded.duration,price='Ask for price',summary=excluded.summary,highlights=excluded.highlights,itinerary=excluded.itinerary,inclusions=excluded.inclusions,exclusions=excluded.exclusions,terms=excluded.terms,cover_path=excluded.cover_path,image_paths=excluded.image_paths,active=true;
